"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import type { AppView } from "../forecast-app";
import type { AuthUser } from "../lib/api";
import { workspaceRequest, downloadForecast } from "../lib/api";
import type { Workspace, Product, Run, Alert, Dashboard, Inventory, Monitor, Member, Job, Preview, QueryResult } from "../lib/workspace-types";
import type { RiskLevel, TrendPoint } from "../lib/demo-data";
import { ForecastChart } from "./ForecastChart";
import { Icon, Button, PageIntro, KpiCard, RiskBadge, TrendValue, DetailStat, EmptyState, TimelineItem, QualityCheck, StepItem, StepLine } from "./workspace-ui";
import "./live-workspace.css";

export type LiveMeta = { workspace: Workspace; pending: number; alerts: {id: string; level: RiskLevel; product: string; title: string}[] };
type State = { info: Workspace; dashboard: Dashboard; products: Product[]; inventory: Inventory[]; runs: Run[]; alerts: Alert[]; jobs: Job[]; monitor: Monitor; members: Member[] };
type Rpc = <T>(path: string, body?: unknown, method?: string) => Promise<T>;
type Context = { state: State; rpc: Rpc; busy: boolean; writer: boolean; manager: boolean; action: (work: () => Promise<void>) => Promise<void>; refresh: () => void; navigate: (path: string) => void; notify: (message: string) => void };
const num = (v: number | null | undefined) => v == null ? "—" : v.toLocaleString("th-TH", { maximumFractionDigits: 2 });
const percent = (v: number | null | undefined) => v == null ? "—" : `${num(v)}%`;
const dateText = (v: string | null | undefined) => v ? new Date(v).toLocaleString("th-TH", { timeZone: "Asia/Bangkok" }) : "—";
const cleanName = (v: string) => v.replace(/ · Mock Demand Lab$/, " · Workspace");
const safeText = (v: string) => v.replace(/\s*\(mock scenario\)\.?/gi, "").replace(/\s*Synthetic sales, verify before acting\./gi, "");
const columns = ["sale_date", "product_code", "region", "sales_quantity", "inventory"];
const columnLabels: Record<string, string> = { sale_date: "Date", product_code: "Product", region: "Region", sales_quantity: "Sales quantity", inventory: "Inventory" };
const modelNames: Record<string, string> = { last_value: "ยอดขายล่าสุด", weekday_mean: "รูปแบบยอดขายรายสัปดาห์", linear_trend: "แนวโน้มยอดขาย", annual_seasonal: "ฤดูกาลรายปี" };

function Panel({title,kicker,children,actions,className=""}: {title:string;kicker?:string;children:ReactNode;actions?:ReactNode;className?:string}) {
  return <article className={`panel live-panel ${className}`}><div className="panel-heading"><div>{kicker&&<span className="panel-kicker">{kicker}</span>}<h3>{title}</h3></div>{actions}</div>{children}</article>;
}
function DataTable({rows,labels}: {rows:Record<string,string|number|null|undefined>[];labels?:Record<string,string>}) {
  if(!rows.length) return <EmptyState title="ยังไม่มีรายการ" detail="รายการจะแสดงหลังจากบันทึกข้อมูล"/>;
  const keys=Object.keys(rows[0]);
  return <div className="data-table-wrap"><table className="data-table"><thead><tr>{keys.map(k=><th key={k}>{labels?.[k]||k}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{keys.map(k=><td key={k}>{row[k]??"—"}</td>)}</tr>)}</tbody></table></div>;
}
function chartData(actual:{date:string;actual:number}[],future:{date:string;forecast:number}[]=[],group=7): TrendPoint[] {
  const result:TrendPoint[]=[];
  for(const [rows,kind] of [[actual,"actual"],[future,"forecast"]] as const){
    for(let i=0;i<rows.length;i+=group){const slice=rows.slice(i,i+group);result.push({label:slice[0].date.slice(5),[kind]:Math.round(slice.reduce((sum,p)=>sum+("actual" in p?p.actual:p.forecast),0)/slice.length)});}
  }
  return result;
}
function currentRun(state:State,code?:string,region?:string) {return state.runs.find(r=>r.data_version===state.info.data_version&&(!code||r.product_code===code)&&(!region||r.region===region));}
function productRisk(state:State,code:string):RiskLevel {
  const alerts=state.alerts.filter(a=>!a.stale&&a.review_status!=="dismissed"&&state.runs.find(r=>r.id===a.forecast_id)?.product_code===code);
  return alerts.some(a=>a.level==="HIGH")?"HIGH":alerts.length?"MEDIUM":"LOW";
}
function Portfolio({state,rows,navigate}: {state:State;rows:Product[];navigate:Context["navigate"]}) {
  return <div className="data-table-wrap"><table className="data-table"><thead><tr><th>สินค้า</th><th>Forecast</th><th>Trend</th><th>Holdout WAPE</th><th>Inventory</th><th>Risk</th><th/></tr></thead><tbody>{rows.map(p=>{
    const run=currentRun(state,p.code); const stock=state.inventory.filter(i=>i.product_code===p.code);
    return <tr key={p.id}><td><div className="table-product"><span className="product-thumb">{p.name[0]}</span><span><strong>{p.name}</strong><small>{p.code}</small></span></div></td><td>{num(run?.total)}<small>{run?` / ${run.horizon} วัน · ${run.region}`:"ยังไม่มี Forecast"}</small></td><td>{run?.change_percent!=null?<TrendValue value={run.change_percent}/>:"—"}</td><td>{percent(run?.metrics.wape_percent)}</td><td>{stock.length?num(stock.reduce((sum,i)=>sum+i.inventory,0)):"—"}</td><td>{run?<RiskBadge risk={productRisk(state,p.code)}/>:<span className="live-muted">ยังไม่ประเมิน</span>}</td><td><button className="icon-button" aria-label={`ดู ${p.name}`} onClick={()=>navigate(`/products/${p.id}`)}><Icon name="chevron"/></button></td></tr>;
  })}</tbody></table>{!rows.length&&<EmptyState title="ยังไม่มีสินค้า" detail="นำเข้ายอดขายเพื่อเพิ่มสินค้าในพื้นที่ทำงาน"/>}</div>;
}

export function LiveWorkspace({token,user,view,path,workspaceId,refreshKey,onMetadata,onNavigate,onLogout,onChangePassword}: {
  token:string;user:AuthUser;view:AppView;path:string;workspaceId:number|null;refreshKey:number;onMetadata:(meta:LiveMeta)=>void;onNavigate:(path:string)=>void;onLogout:()=>Promise<void>;onChangePassword:(values:{current_password:string;new_password:string})=>Promise<void>;
}) {
  const [state,setState]=useState<State|null>(null);
  const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [notice,setNotice]=useState("");
  const [busy,setBusy]=useState(false);const actionLock=useRef(false);const [reload,setReload]=useState(0);
  useEffect(()=>{
    let alive=true;const controller=new AbortController();
    async function load(){try{
      const info=await workspaceRequest<Workspace>(token,workspaceId,"",undefined,undefined,controller.signal);
      const call=<T,>(p:string)=>workspaceRequest<T>(token,info.id,p,undefined,undefined,controller.signal);
      const [dashboard,products,inventory,runs,alerts,jobs,monitor,members]=await Promise.all([call<Dashboard>("/dashboard"),call<Product[]>("/products"),call<Inventory[]>("/inventory"),call<Run[]>("/forecasts"),call<Alert[]>("/alerts"),call<Job[]>("/imports"),call<Monitor>("/monitoring"),call<Member[]>("/members")]);
      if(!alive)return;
      const next={info,dashboard,products,inventory,runs,alerts,jobs,monitor,members};setState(next);setError("");
      onMetadata({workspace:info,pending:dashboard.pending_alerts,alerts:alerts.filter(a=>!a.stale&&a.review_status==="pending").map(a=>{const run=runs.find(r=>r.id===a.forecast_id);return {id:String(a.id),level:a.level as RiskLevel,product:products.find(p=>p.code===run?.product_code)?.name||"Forecast",title:safeText(a.message)};})});
    }catch(e){if(alive)setError(e instanceof Error?e.message:"โหลดข้อมูลไม่ได้");}finally{if(alive)setLoading(false);}}
    void load();return()=>{alive=false;controller.abort();};
  },[token,workspaceId,reload,refreshKey,onMetadata]);
  useEffect(()=>{if(!state||(state.info.settings.auto_refresh===false))return;const timer=setInterval(()=>setReload(v=>v+1),15*60*1000);return()=>clearInterval(timer);},[state]);
  const action=useCallback(async(work:()=>Promise<void>)=>{if(actionLock.current)return;actionLock.current=true;setBusy(true);setError("");setNotice("");try{await work();}catch(e){setError(e instanceof Error?e.message:"เกิดข้อผิดพลาด");}finally{actionLock.current=false;setBusy(false);}},[]);
  const rpc:Rpc=(p,body,method)=>workspaceRequest(token,state?.info.id??workspaceId,p,body,method);
  const ctx:Context|null=state?{state,rpc,busy,writer:state.info.role!=="viewer",manager:["owner","admin"].includes(state.info.role),action,refresh:()=>setReload(v=>v+1),navigate:onNavigate,notify:setNotice}:null;
  return <div className={`live-workspace ${state?.info.settings.compact_table?"live-compact":""}`}>
    {(error||notice||busy)&&<div className="page-content live-feedback">{error&&<div className="live-error" role="alert">{error}<Button variant="secondary" onClick={()=>setReload(v=>v+1)} disabled={busy}>ลองใหม่</Button></div>}{notice&&<div className="live-notice" role="status"><Icon name="check"/>{notice}</div>}{busy&&<div className="live-processing" role="status"><span className="spinner-dot"/>กำลังประมวลผล กรุณารอ</div>}</div>}
    {loading?<div className="page-content"><Panel title="กำลังโหลดพื้นที่ทำงาน"><p role="status">กำลังอ่านข้อมูลจากฐานข้อมูล...</p></Panel></div>:!state?<div className="page-content"><EmptyState title="เชื่อมต่อพื้นที่ทำงานไม่ได้" detail="ตรวจสอบว่า API และฐานข้อมูลทำงานอยู่" action="ลองใหม่" onClick={()=>setReload(v=>v+1)}/></div>:<>
      {view==="dashboard"&&<LiveDashboard ctx={ctx!} user={user}/>}
      {view==="forecast"&&<LiveForecast ctx={ctx!} path={path} token={token}/>}
      {view==="data"&&<LiveData ctx={ctx!}/>}
      {view==="products"&&<LiveProducts ctx={ctx!} path={path}/>}
      {view==="alerts"&&<LiveAlerts ctx={ctx!} path={path}/>}
      {view==="monitoring"&&<LiveMonitoring ctx={ctx!}/>}
      {view==="settings"&&<LiveSettings key={path} ctx={ctx!} user={user} path={path} onLogout={onLogout} onChangePassword={onChangePassword}/>}
    </>}
  </div>;
}

function LiveDashboard({ctx,user}: {ctx:Context;user:AuthUser}) {
  const {state,navigate}=ctx;const {dashboard,products,alerts,runs}=state;const [chartCode,setChartCode]=useState("");
  const run=chartCode?currentRun(state,chartCode):undefined;const latest=dashboard.latest_forecast;
  const pending=alerts.filter(a=>!a.stale&&a.review_status==="pending");const high=pending.filter(a=>a.level==="HIGH");
  const liveRuns=runs.filter(r=>r.data_version===state.info.data_version);const wapes=liveRuns.map(r=>r.metrics.wape_percent).filter((v):v is number=>v!=null);
  const totalSales=dashboard.regions.reduce((sum,r)=>sum+r.quantity,0);
  const colors=["#0e9f91","#4c77d8","#8368d9","#ee8b33","#58bbc5"];
  const donut=dashboard.regions.map((r,i)=>{const start=dashboard.regions.slice(0,i).reduce((sum,v)=>sum+v.quantity,0)/Math.max(1,totalSales)*100;const end=start+r.quantity/Math.max(1,totalSales)*100;return `${colors[i%colors.length]} ${start}% ${end}%`;}).join(",");
  return <div className="page-content dashboard-page"><PageIntro title={`สวัสดีครับ, คุณ${user.full_name||user.username} 👋`} description="ตรวจสอบยอดขาย แนวโน้ม และรายการที่ต้องตัดสินใจจากข้อมูลล่าสุดของพื้นที่ทำงาน" actions={<><Button variant="secondary" icon="upload" onClick={()=>navigate("/data/upload")}>นำเข้าข้อมูล</Button><Button icon="plus" onClick={()=>navigate("/forecast/new")}>สร้าง Forecast ใหม่</Button></>}/>
    <section className="kpi-grid" aria-label="ตัวชี้วัดหลัก"><KpiCard label="Forecast demand" value={num(latest?.total)} detail={latest?`${latest.product_code} · ${latest.region} · ${latest.horizon} วัน`:"ยังไม่มี Forecast สำหรับข้อมูลรุ่นนี้"} change={latest?percent(latest.change_percent):"รอคำนวณ"} tone="teal" icon="trend" isTextChange/><KpiCard label="Holdout WAPE" value={percent(wapes.length?wapes.reduce((a,b)=>a+b,0)/wapes.length:null)} detail="ค่าเฉลี่ยความคลาดเคลื่อนย้อนหลัง 28 วัน" change="ยิ่งต่ำยิ่งดี" tone="blue" icon="shield" isTextChange/><KpiCard label="High priority alerts" value={num(high.length)} detail="รายการปัจจุบันที่ยังไม่ทบทวน" change={high.length?"ต้องตรวจสอบ":"ไม่มีรายการค้าง"} tone="orange" icon="bell" isTextChange/><KpiCard label="Sales records" value={num(dashboard.records)} detail={`ข้อมูลถึง ${dashboard.last_date||"—"}`} change={`รุ่น ${dashboard.data_version}`} tone="purple" icon="database" isTextChange/></section>
    {!dashboard.records&&<EmptyState title="เริ่มต้นพื้นที่ทำงานของคุณ" detail="นำเข้าข้อมูลยอดขายและ Inventory เพื่อแสดงภาพรวมและเริ่มพยากรณ์" action="นำเข้าข้อมูล" onClick={()=>navigate("/data/upload")}/>}
    <section className="dashboard-primary-grid"><article className="panel chart-panel"><div className="panel-heading"><div><span className="panel-kicker">Demand overview</span><h3>แนวโน้ม Actual vs Forecast</h3></div><select className="select-button" aria-label="สินค้าบนกราฟ" value={chartCode} onChange={e=>setChartCode(e.target.value)}><option value="">ยอดขายรวมทุกสินค้า</option>{products.map(p=><option value={p.code} key={p.id}>{p.name}</option>)}</select></div><div className="chart-summary"><strong>{num(chartCode?run?.total:dashboard.recent_sales)} <small>units</small></strong><span>{chartCode?(run?`${run.region} · ${run.horizon} วัน`:"ยังไม่มี Forecast สำหรับสินค้านี้"):"ยอดขาย 30 วันล่าสุด"}</span></div><ForecastChart units="units" unitsLabel="เฉลี่ยชิ้น/วัน (ช่วงละ 7 วัน)" markerLabel="Forecast" data={chartCode?chartData(run?.history||[],run?.points||[]):chartData(dashboard.trend)}/></article>
      <article className="panel insight-panel"><div className="ai-badge"><Icon name="spark"/>DEMAND INSIGHT</div><h3>{latest?"แนวโน้มจาก Forecast ล่าสุด":"พร้อมวิเคราะห์ Demand"}</h3><p className="insight-lead">{latest?<>{products.find(p=>p.code===latest.product_code)?.name||latest.product_code} · {latest.region}<br/>แนวโน้ม {percent(latest.change_percent)} เทียบค่าเฉลี่ย 28 วัน</>:"สร้าง Forecast เพื่อประเมินแนวโน้ม ความคลาดเคลื่อน และความเสี่ยงคงคลัง"}</p><div className="insight-visual"><div className="insight-ring"><span>{num(latest?.change_percent)}<small>%</small></span></div><div><span className="mini-label">Holdout WAPE</span><strong>{percent(latest?.metrics.wape_percent)}</strong><small>ความคลาดเคลื่อนจากยอดขายย้อนหลัง</small></div></div><div className="insight-divider"/><div className="insight-reason"><Icon name="spark"/><span><strong>{latest?modelNames[latest.model]:"เลือกโมเดลจากข้อมูลยอดขาย"}</strong><small>{latest?`ประเมิน ณ ${latest.origin}`:"ประเมินผลก่อนใช้วางแผน"}</small></span></div><Button variant="secondary" onClick={()=>navigate(latest?`/forecast/${latest.id}`:"/forecast/new")}>{latest?"ดูผล Forecast":"สร้าง Forecast"}<Icon name="arrow"/></Button></article></section>
    <section className="dashboard-secondary-grid"><article className="panel table-panel"><div className="panel-heading"><div><span className="panel-kicker">Portfolio health</span><h3>สินค้าที่ต้องจับตา</h3></div><button className="text-button" onClick={()=>navigate("/products")}>ดูทั้งหมด<Icon name="arrow"/></button></div><Portfolio state={state} rows={products.slice(0,4)} navigate={navigate}/></article><article className="panel region-panel"><div className="panel-heading"><div><span className="panel-kicker">Demand contribution</span><h3>สัดส่วนยอดขายตาม Region</h3></div></div><div className="region-donut" style={{background:donut?`conic-gradient(${donut})`:"#e7ebf0"}}><div className="donut-center"><strong>{num(totalSales)}</strong><span>total units</span></div></div><div className="region-list">{dashboard.regions.map((r,i)=><div className="region-row" key={r.region}><span className="region-dot" style={{background:colors[i%colors.length]}}/><span>{r.region}</span><strong>{percent(totalSales?r.quantity/totalSales*100:0)}</strong></div>)}</div></article><article className="panel alerts-panel"><div className="panel-heading"><div><span className="panel-kicker">Early warning</span><h3>แจ้งเตือนล่าสุด <span className="heading-count">{pending.length}</span></h3></div><button className="text-button" onClick={()=>navigate("/alerts")}>ดูทั้งหมด<Icon name="arrow"/></button></div><div className="alert-mini-list">{pending.slice(0,4).map(a=><button className="alert-mini-row" key={a.id} onClick={()=>navigate(`/alerts/${a.id}`)}><span className={`alert-level-dot dot-${a.level.toLowerCase()}`}/><span className="alert-mini-copy"><strong>Forecast #{a.forecast_id}</strong><small>{safeText(a.message)}</small></span></button>)}</div>{!pending.length&&<p className="live-muted">ไม่มีรายการรอทบทวน</p>}<button className="alert-setup-link" onClick={ctx.refresh}><Icon name="refresh"/>รีเฟรชข้อมูลล่าสุด</button></article></section>
    <section className="journey-strip"><div className="journey-strip-copy"><span className="journey-kicker">CORE JOURNEY</span><strong>Data → Forecast → Insight → Decision</strong><span>ข้อมูลและการตัดสินใจบันทึกในพื้นที่ทำงาน</span></div><div className="journey-steps">{["Data","Forecast","Review","Monitor"].map((s,i)=><button key={s} className="journey-step" onClick={()=>navigate(["/data/upload","/forecast/new","/alerts","/monitoring"][i])}><i>{i+1}</i>{s}</button>)}</div></section>
  </div>;
}

function ForecastResult({ctx,run,token,onReset}: {ctx:Context;run:Run;token:string;onReset:()=>void}) {
  const product=ctx.state.products.find(p=>p.code===run.product_code);const stock=run.inventory_snapshot===undefined?ctx.state.inventory.find(i=>i.product_code===run.product_code&&i.region===run.region&&i.sale_date<=run.origin):run.inventory_snapshot;
  const cover=stock&&run.total>0?stock.inventory/(run.total/run.horizon):null;
  return <div className="forecast-result"><div className="result-banner"><div className="result-banner-icon"><Icon name="check"/></div><div><span className="panel-kicker">Forecast #{run.id} · {dateText(run.created_at)}</span><h3>พร้อมใช้ผลลัพธ์เพื่อวางแผน</h3><p>{run.product_code} · {run.region} · ข้อมูล ณ {run.origin}{run.data_version!==ctx.state.info.data_version&&" · ผลจากข้อมูลรุ่นก่อน"}</p></div><Button variant="secondary" icon="download" disabled={ctx.busy} onClick={()=>void ctx.action(()=>downloadForecast(token,ctx.state.info.id,run.id))}>Export report</Button></div><section className="result-kpi-grid"><article className="result-kpi-card result-kpi-highlight"><span className="panel-kicker">Next {run.horizon} days forecast</span><strong>{num(run.total)}</strong><small>units · {product?.name||run.product_code} · {run.region}</small>{run.change_percent!=null&&<TrendValue value={run.change_percent}/>}</article><article className="result-kpi-card"><span className="panel-kicker">Holdout WAPE</span><strong>{percent(run.metrics.wape_percent)}</strong><small>ความคลาดเคลื่อนรวมย้อนหลัง 28 วัน</small></article><article className="result-kpi-card"><span className="panel-kicker">Holdout MAE</span><strong>{num(run.metrics.mae)}</strong><small>ความคลาดเคลื่อนเฉลี่ย · หน่วย/วัน</small></article><article className="result-kpi-card"><span className="panel-kicker">Inventory cover</span><strong>{num(cover)} <small>วัน</small></strong><small>{stock?`Snapshot ณ ${stock.sale_date}`:"ยังไม่มี Inventory snapshot"}</small></article></section><section className="result-main-grid"><article className="panel chart-panel"><div className="panel-heading"><div><span className="panel-kicker">Demand analysis</span><h3>Actual vs Forecast</h3></div></div><ForecastChart units="units" unitsLabel="เฉลี่ยชิ้น/วัน (ช่วงละ 7 วัน)" markerLabel="Forecast" data={chartData(run.history.slice(-60),run.points)}/></article><aside className="panel factor-panel"><div className="panel-heading"><div><span className="panel-kicker">Model selection</span><h3>โมเดลและการประเมินผล</h3></div></div><h4>{modelNames[run.model]||run.model}</h4><p>เลือกจาก validation ย้อนหลัง 2 ช่วง แล้วประเมินอีก 28 วันท้ายที่ไม่ใช้เลือกโมเดล</p><div className="factor-list">{Object.entries(run.selection_mae).map(([model,mae])=><div className="factor-row" key={model}><span className="factor-dot factor-dot-teal"/><span><strong>{modelNames[model]||model}</strong><small>Validation MAE</small></span><b>{num(mae)}</b></div>)}</div><p>ช่วงค่าต่ำ–สูงคำนวณจากความคลาดเคลื่อนย้อนหลังและขยายตามระยะพยากรณ์ ไม่ใช่เปอร์เซ็นต์ความมั่นใจ</p><p>วันขาดหายที่เติมศูนย์: {num(run.missing_days_filled_zero)}</p></aside></section><Panel title="ยอดพยากรณ์รายวันและช่วงความไม่แน่นอน" kicker="Forecast detail"><DataTable rows={run.points.map(p=>({Date:p.date,Forecast:p.forecast,Lower:p.lower,Upper:p.upper}))}/></Panel><section className="decision-panel panel"><div><span className="panel-kicker">Next best action</span><h3>คุณต้องการทำอะไรต่อ?</h3><p>ทบทวนผลก่อนสรุปแผน Production หรือ Inventory</p></div><div className="decision-actions"><Button variant="secondary" onClick={()=>ctx.navigate("/alerts")}>ทบทวน Alert</Button><Button onClick={()=>ctx.navigate(product?`/products/${product.id}`:"/products")}>ดู Product detail</Button><button className="text-button" onClick={onReset}>สร้าง Forecast ใหม่</button></div></section></div>;
}

function LiveForecast({ctx,path,token}: {ctx:Context;path:string;token:string}) {
  const [code,setCode]=useState("");const [region,setRegion]=useState("");const [horizon,setHorizon]=useState(30);const [asOf,setAsOf]=useState("");const [missing,setMissing]=useState(false);const [result,setResult]=useState<Run|null>(null);const [running,setRunning]=useState(false);
  const params=new URLSearchParams(path.split("?")[1]);const selectedCode=code||params.get("product")||ctx.state.products[0]?.code||"";
  const selectedRegion=region||params.get("region")||ctx.state.dashboard.regions[0]?.region||"";
  const routeId=Number(path.split("?")[0].split("/")[2]);const routeRun=ctx.state.runs.find(r=>r.id===routeId);
  const run=routeId?(result?.id===routeId?result:routeRun):null;const previous=currentRun(ctx.state,selectedCode,selectedRegion);
  const [routeError,setRouteError]=useState("");
  const rpc=ctx.rpc;const infoId=ctx.state.info.id;
  useEffect(()=>{if(!routeId||routeRun)return;let alive=true;async function load(){try{const fetched=await rpc<Run>(`/forecasts/${routeId}`);if(alive){setResult(fetched);setRouteError("");}}catch(e){if(alive)setRouteError(e instanceof Error?e.message:"ไม่พบ Forecast");}}void load();return()=>{alive=false;};
    // Direct links can point to runs older than the recent history list.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  },[routeId,infoId,!!routeRun]);
  async function submit(e:FormEvent){e.preventDefault();await ctx.action(async()=>{setRunning(true);try{const next=await ctx.rpc<Run>("/forecasts",{product_code:selectedCode,region:selectedRegion,horizon,signals:[],acknowledge_missing_days:missing,as_of:asOf||null});setResult(next);ctx.navigate(`/forecast/${next.id}`);ctx.notify(`Forecast #${next.id} คำนวณและบันทึกเรียบร้อย`);ctx.refresh();}finally{setRunning(false);}});}
  function reset(){setResult(null);ctx.navigate("/forecast/new");}
  return <div className="page-content forecast-page"><PageIntro title={run?"ผลการพยากรณ์ Demand":"สร้าง Forecast ใหม่"} description="ใช้ยอดขายย้อนหลัง เลือกโมเดลจากผลทดสอบ และบันทึกผลสำหรับติดตามการวางแผน" actions={<Button variant="secondary" icon="help" onClick={()=>ctx.navigate("/settings?section=help")}>ดูวิธีใช้งาน</Button>}/><div className="journey-stepper"><StepItem number="1" label="ตั้งค่า Forecast" active={!run&&!running} complete={!!run||running}/><StepLine complete={!!run||running}/><StepItem number="2" label="กำลังวิเคราะห์" active={running} complete={!!run}/><StepLine complete={!!run}/><StepItem number="3" label="ดูผลลัพธ์และตัดสินใจ" active={!!run} complete={false}/></div>
    {routeId&&!run&&!running?<Panel title={routeError?"ไม่พบ Forecast นี้":"กำลังอ่านผล Forecast"}><p role={routeError?"alert":"status"}>{routeError||"กำลังโหลดผลที่บันทึกไว้..."}</p><Button onClick={reset}>สร้าง Forecast ใหม่</Button></Panel>:running?<div className="running-state panel" role="status"><div className="running-orbit"><span className="orbit-ring ring-one"/><span className="running-core"><Icon name="spark"/></span></div><h3>กำลังคำนวณ Forecast</h3><p>กำลังทดสอบโมเดลกับข้อมูลย้อนหลังและบันทึกผล</p></div>:run?<ForecastResult ctx={ctx} run={run} token={token} onReset={reset}/>:<div className="forecast-setup-grid"><form className="panel setup-form-panel" onSubmit={submit}><div className="panel-heading"><div><span className="panel-kicker">Forecast parameters</span><h3>ข้อมูลที่ต้องการ Forecast</h3></div><span className="setup-required"><span>*</span> จำเป็นต้องกรอก</span></div><div className="form-grid"><label className="form-field"><span>สินค้า <em>*</em></span><select required value={selectedCode} onChange={e=>setCode(e.target.value)}><option value="">เลือกสินค้า</option>{ctx.state.products.map(p=><option key={p.id} value={p.code}>{p.name} · {p.code}</option>)}</select></label><label className="form-field"><span>Region <em>*</em></span><select required value={selectedRegion} onChange={e=>setRegion(e.target.value)}><option value="">เลือกพื้นที่</option>{ctx.state.dashboard.regions.map(r=><option key={r.region}>{r.region}</option>)}</select></label></div><div className="form-field period-field"><span>ช่วงเวลา Forecast <em>*</em></span><div className="period-options">{[{days:30,label:"1 เดือน",note:"Quick view"},{days:90,label:"3 เดือน",note:"Planning"},{days:180,label:"6 เดือน",note:"Long range"}].map(p=><button key={p.days} type="button" className={horizon===p.days?"is-selected":""} onClick={()=>setHorizon(p.days)}>{p.label}<small>{p.note}</small></button>)}</div></div><div className="form-grid"><label className="form-field"><span>จำนวนวัน (7–180 วัน)</span><input type="number" min="7" max="180" required value={horizon} onChange={e=>setHorizon(Number(e.target.value))}/></label><label className="form-field"><span>พยากรณ์ ณ วันที่</span><input type="date" max={ctx.state.dashboard.last_date||undefined} value={asOf} onChange={e=>setAsOf(e.target.value)}/><small>เว้นว่างเพื่อใช้วันล่าสุดของข้อมูล</small></label></div><div className="live-method"><Icon name="shield"/><span>วิเคราะห์แนวโน้มและฤดูกาลจากยอดขายของพื้นที่ที่เลือก ใช้ประวัติอย่างน้อย 112 วันปฏิทินและ 56 วันที่มีรายการ</span></div><label className="live-check"><input type="checkbox" checked={missing} onChange={e=>setMissing(e.target.checked)}/> หากมีวันขาดหาย ยืนยันให้ตีความยอดขายเป็นศูนย์</label><div className="setup-form-footer"><span>{!ctx.writer?"สิทธิ์ Viewer อ่านผลได้อย่างเดียว":"ผลจะบันทึกพร้อมรุ่นข้อมูลและวันต้นกำเนิด"}</span><Button type="submit" icon="trend" disabled={ctx.busy||!ctx.writer||!selectedCode||!selectedRegion}>Run Forecast</Button></div></form><aside className="forecast-preview-card"><div className="preview-card-top"><span className="ai-badge"><Icon name="spark"/>FORECAST READY</span></div><h3>ผลล่าสุดของสินค้าที่เลือก</h3><p>{previous?`${previous.region} · ${previous.horizon} วัน · ข้อมูล ณ ${previous.origin}`:"ยังไม่มีผลพยากรณ์สำหรับข้อมูลปัจจุบัน"}</p><div className="preview-metric"><span>Forecast demand</span><strong>{num(previous?.total)} <small>units</small></strong>{previous?.change_percent!=null&&<TrendValue value={previous.change_percent}/>}</div><div className="preview-divider"/><div className="preview-list"><span><span><strong>Holdout WAPE</strong><small>ความคลาดเคลื่อนย้อนหลัง</small></span><b>{percent(previous?.metrics.wape_percent)}</b></span><span><span><strong>Model</strong><small>เลือกจาก validation</small></span><b>{previous?modelNames[previous.model]:"—"}</b></span></div>{!ctx.state.products.length&&<Button onClick={()=>ctx.navigate("/data/upload")}>นำเข้าข้อมูลก่อนเริ่ม</Button>}</aside></div>}
    <Panel title="ประวัติ Forecast" kicker="Saved forecasts"><div className="data-table-wrap"><table className="data-table"><thead><tr><th>รายการ</th><th>สินค้า / Region</th><th>ระยะ</th><th>Forecast</th><th>WAPE</th><th>ข้อมูล</th><th/></tr></thead><tbody>{ctx.state.runs.map(r=><tr key={r.id}><td>#{r.id}<small>{dateText(r.created_at)}</small></td><td>{r.product_code} / {r.region}</td><td>{r.horizon} วัน</td><td>{num(r.total)}</td><td>{percent(r.metrics.wape_percent)}</td><td>{r.data_version===ctx.state.info.data_version?"ปัจจุบัน":"รุ่นก่อน"}</td><td><button className="text-button" onClick={()=>{setResult(null);ctx.navigate(`/forecast/${r.id}`);}}>ดูผล</button><button className="text-button" disabled={!ctx.writer||ctx.busy} onClick={()=>{setResult(null);setCode(r.product_code);setRegion(r.region);setHorizon(r.horizon);setAsOf("");ctx.navigate("/forecast/new");}}>Re-forecast</button></td></tr>)}</tbody></table></div>{!ctx.state.runs.length&&<EmptyState title="ยังไม่มี Forecast" detail="สร้างผลพยากรณ์แรกจากข้อมูลยอดขายของคุณ"/>}</Panel>
  </div>;
}

function downloadText(filename:string,text:string) {
  const url=URL.createObjectURL(new Blob(["\ufeff",text],{type:"text/csv;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function downloadCsv(filename:string,rows:Record<string,string|number|null|undefined>[]) {
  const keys=Object.keys(rows[0]||{});const quote=(v:unknown)=>'"'+(typeof v==="string"&&/^[=+@\-\t\r]/.test(v)?"'":"")+String(v??"").replaceAll('"','""')+'"';
  const text=[keys.map(quote).join(","),...rows.map(row=>keys.map(k=>quote(row[k])).join(","))].join("\r\n");
  downloadText(filename,text);
}
function LiveData({ctx}: {ctx:Context}) {
  const [step,setStep]=useState<"upload"|"preview"|"mapping"|"quality">("upload");const [file,setFile]=useState<{filename:string;content_base64:string}|null>(null);const [preview,setPreview]=useState<Preview|null>(null);const [mapping,setMapping]=useState<Record<string,string>>({});const [job,setJob]=useState<Job|null>(null);const [mode,setMode]=useState("append");const [duplicates,setDuplicates]=useState(false);const [code,setCode]=useState("");const [region,setRegion]=useState("");const [query,setQuery]=useState<QueryResult|null>(null);
  const steps=[{id:"upload",label:"อัปโหลดไฟล์",caption:"CSV / Excel"},{id:"preview",label:"Preview",caption:"ตรวจข้อมูลเบื้องต้น"},{id:"mapping",label:"Column mapping",caption:"จับคู่ field"},{id:"quality",label:"Data quality",caption:"ตรวจสอบก่อน Forecast"}] as const;
  const index=steps.findIndex(s=>s.id===step);
  async function pick(selected:File|undefined){if(!selected||!ctx.writer)return;await ctx.action(async()=>{
    if(selected.size>20*1024*1024)throw new Error("ไฟล์ต้องไม่เกิน 20 MB");
    if(!/\.(csv|xlsx)$/i.test(selected.name))throw new Error("รองรับไฟล์ CSV และ XLSX เท่านั้น");
    const content=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]);reader.onerror=()=>reject(new Error("อ่านไฟล์ไม่ได้"));reader.readAsDataURL(selected);});
    const payload={filename:selected.name,content_base64:content};const result=await ctx.rpc<Preview>("/imports/preview",payload);setFile(payload);setPreview(result);setMapping(result.suggested_mapping);setJob(null);setDuplicates(false);setStep("preview");
  });}
  async function validate(){if(!file)return;await ctx.action(async()=>{const next=await ctx.rpc<Job>("/imports/validate",{...file,mapping});setJob(next);setDuplicates(false);setStep("quality");ctx.refresh();});}
  async function commit(){if(!job)return;await ctx.action(async()=>{const saved=await ctx.rpc<Job>(`/imports/${job.id}/commit`,{mode,acknowledge_duplicates:duplicates});setJob(saved);ctx.notify(`บันทึก ${num(saved.report.valid_rows)} รายการเรียบร้อย`);ctx.refresh();});}
  const report=job?.report;
  return <div className="page-content data-page"><PageIntro title="นำเข้าข้อมูลบริษัท" description="นำเข้า Sales และ Inventory ตรวจสอบคุณภาพ แล้วบันทึกเพื่อใช้วางแผน" actions={<Button variant="secondary" icon="download" onClick={()=>downloadText("sales-template.csv",columns.join(",")+"\r\n")}>ดาวน์โหลด Template</Button>}/><div className="data-stepper">{steps.map((s,i)=><button className={`data-step ${s.id===step?"is-active":""} ${i<index?"is-complete":""}`} key={s.id} disabled={ctx.busy||(i===1||i===2)&&!preview||i===3&&!job} onClick={()=>setStep(s.id)}><span>{i<index?<Icon name="check"/>:i+1}</span><div><strong>{s.label}</strong><small>{s.caption}</small></div></button>)}</div>
    {step==="upload"&&<><div className="upload-layout"><article className="panel upload-panel"><span className="panel-kicker">Step 1 · Data onboarding</span><h3>อัปโหลดไฟล์ยอดขายและ Inventory</h3><p>CSV UTF-8 หรือ Excel .xlsx แผ่นแรก · ไม่เกิน 20 MB / 250,000 แถว</p><div className="upload-dropzone" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();if(!ctx.busy)void pick(e.dataTransfer.files?.[0]);}}><span className="upload-icon"><Icon name="upload"/></span><strong>ลากไฟล์มาวางที่นี่</strong><label className="live-file-button">เลือกไฟล์จากเครื่อง<input type="file" accept=".csv,.xlsx" disabled={ctx.busy||!ctx.writer} onChange={e=>void pick(e.target.files?.[0])}/></label><small>CSV / XLSX · สูงสุด 20 MB</small></div>{file&&<p>{file.filename}</p>}{!ctx.writer&&<p>สิทธิ์ Viewer อ่านข้อมูลได้อย่างเดียว</p>}</article><aside className="panel upload-guide"><h3>ข้อมูลที่ระบบต้องการ</h3><p>ตรวจสอบชื่อคอลัมน์และหน่วยก่อนบันทึก</p><div className="guide-field-list">{columns.map((c,i)=><div key={c}><span>{i+1}</span><strong>{columnLabels[c]}</strong><small>{c}</small></div>)}</div><p>Inventory เป็นค่าคงคลัง ณ วันที่ระบุ ไม่ใช่ยอดขายสะสม</p></aside></div></>}
    {step==="preview"&&preview&&<Panel title="ตรวจสอบข้อมูลเบื้องต้น" kicker="Step 2 · Preview"><p>{file?.filename} · {num(preview.total_rows)} รายการ · แสดง {preview.preview.length} รายการแรก</p><DataTable rows={preview.preview}/><div className="data-panel-footer"><span>ตรวจการจับคู่คอลัมน์ก่อนตรวจคุณภาพ</span><Button onClick={()=>setStep("mapping")} icon="arrow">ตรวจสอบ Column mapping</Button></div></Panel>}
    {step==="mapping"&&preview&&<div className="mapping-layout"><Panel title="ยืนยันการจับคู่ข้อมูล" kicker="Step 3 · Column mapping"><div className="mapping-list">{columns.map(c=><div className="mapping-row" key={c}><span className="mapping-target">{columnLabels[c]}{c!=="inventory"&&" *"}</span><Icon name="arrow"/><label className="form-field"><select aria-label={`คอลัมน์ ${columnLabels[c]}`} value={mapping[c]||""} onChange={e=>{setMapping({...mapping,[c]:e.target.value});setJob(null);}}><option value="">{c==="inventory"?"ไม่ใช้ Inventory":"เลือกคอลัมน์"}</option>{preview.headers.map(h=><option key={h}>{h}</option>)}</select></label></div>)}</div><div className="data-panel-footer"><Button variant="secondary" onClick={()=>setStep("preview")}>ย้อนกลับ</Button><Button icon="arrow" disabled={ctx.busy||!ctx.writer||columns.filter(c=>c!=="inventory").some(c=>!mapping[c])} onClick={()=>void validate()}>ตรวจสอบ Data quality</Button></div></Panel><aside className="panel mapping-tip"><h3>Column mapping คืออะไร?</h3><p>จับคู่คอลัมน์จากไฟล์เข้ากับ Date, Product, Region และยอดขาย ระบบจะตรวจทุกแถวก่อนอนุญาตให้บันทึก</p></aside></div>}
    {step==="quality"&&job&&report&&<div className="quality-layout"><article className="panel quality-summary"><div className="quality-header"><div><span className="panel-kicker">Step 4 · Data quality</span><h3>{report.invalid_rows?"ต้องแก้ไขข้อมูลก่อนบันทึก":job.status==="committed"?"บันทึกข้อมูลแล้ว":"ข้อมูลพร้อมสำหรับบันทึก"}</h3><p>{job.filename} · {num(report.total_rows)} รายการ</p></div><div className="quality-score"><strong>{num(report.quality_percent)}</strong><span>/100</span><small>Data quality score</small></div></div><div className="quality-bar"><i style={{width:`${report.quality_percent}%`}}/></div><div className="quality-checks"><QualityCheck title="Validity" detail="แถวที่ถูกต้อง" value={num(report.valid_rows)} tone={report.invalid_rows?"warning":"good"}/><QualityCheck title="Invalid rows" detail="แถวที่ต้องแก้ไขก่อนบันทึก" value={num(report.invalid_rows)} tone={report.invalid_rows?"warning":"good"}/><QualityCheck title="Duplicates" detail="รายการที่เหมือนกันทุกค่า" value={num(report.exact_duplicate_rows)} tone={report.exact_duplicate_rows?"warning":"good"}/><QualityCheck title="Coverage" detail="ช่วงวันที่ของข้อมูล" value={`${report.start_date} – ${report.end_date}`} tone="good"/></div><p>Inventory ว่าง {num(report.missing_inventory)} รายการ</p><DataTable rows={report.preview} labels={columnLabels}/>{!!report.errors.length&&<><h4>รายการที่ต้องแก้ไข (สูงสุด 100)</h4><DataTable rows={report.errors} labels={{row:"แถว",error:"ข้อผิดพลาด"}}/></>}{job.status!=="committed"&&<><label className="form-field live-spacing"><span>วิธีบันทึกข้อมูล</span><select value={mode} onChange={e=>setMode(e.target.value)}><option value="append">เพิ่มข้อมูลในชุดเดิม</option><option value="replace">แทนที่ยอดขายเดิมทั้งหมดของพื้นที่ทำงาน</option></select></label>{mode==="replace"&&<p className="live-warning">การบันทึกนี้จะแทนที่ยอดขายเดิมทั้งหมด ผล Forecast เดิมจะเก็บไว้เป็นประวัติ</p>}{!!report.exact_duplicate_rows&&<label className="live-check"><input type="checkbox" checked={duplicates} onChange={e=>setDuplicates(e.target.checked)}/> ยืนยันให้เก็บรายการซ้ำ เพราะเป็นธุรกรรมที่ต้องการนำเข้า</label>}</>}<div className="quality-actions"><Button variant="secondary" onClick={()=>setStep("upload")}>เลือกไฟล์ใหม่</Button>{job.status==="committed"?<Button icon="trend" onClick={()=>ctx.navigate("/forecast/new")}>ใช้ข้อมูลนี้สร้าง Forecast</Button>:<Button icon="check" disabled={ctx.busy||!ctx.writer||!!report.invalid_rows||!!report.exact_duplicate_rows&&!duplicates} onClick={()=>void commit()}>บันทึกข้อมูล</Button>}</div></article><aside className="panel quality-issue"><span className="panel-kicker">Validation report</span><h3>ตรวจสอบก่อนนำเข้า</h3><p>ระบบไม่บันทึกแถวใดหากยังมีข้อมูลผิดพลาด และไม่ลบรายการซ้ำเองโดยไม่ผ่านการทบทวน</p><p>งานนำเข้า #{job.id} · {job.status==="committed"?"บันทึกแล้ว":"ผ่านการตรวจสอบไฟล์"}</p></aside></div>}
    <Panel title="ประวัติการนำเข้า" kicker="Import history"><DataTable rows={ctx.state.jobs.map(j=>({Job:j.id,File:j.filename,Status:j.status==="committed"?"บันทึกแล้ว":"ตรวจแล้ว",Rows:j.report.valid_rows,Date:dateText(j.created_at)}))}/></Panel>
    <Panel title="ค้นหารายการยอดขายและตรวจประสิทธิภาพ" kicker="Database query"><div className="live-toolbar"><label className="form-field"><span>สินค้า</span><select value={code} onChange={e=>setCode(e.target.value)}><option value="">ทุกสินค้า</option>{ctx.state.products.map(p=><option value={p.code} key={p.id}>{p.name}</option>)}</select></label><label className="form-field"><span>Region</span><select value={region} onChange={e=>setRegion(e.target.value)}><option value="">ทุกพื้นที่</option>{ctx.state.dashboard.regions.map(r=><option key={r.region}>{r.region}</option>)}</select></label><Button disabled={ctx.busy} icon="search" onClick={()=>void ctx.action(async()=>{const params=new URLSearchParams();if(code)params.set("product_code",code);if(region)params.set("region",region);setQuery(await ctx.rpc<QueryResult>(`/sales/query?${params}`));})}>ค้นหา</Button></div>{query&&<><p>Query time {num(query.query_ms)} ms · แสดงไม่เกิน 50 รายการ</p><DataTable rows={query.items}/><details className="live-details"><summary>Query plan / Index</summary><pre>{JSON.stringify(query.plan,null,2)}</pre></details></>}</Panel>
  </div>;
}

type ProductSummary = {code:string;last_date:string|null;recent_sales:number;daily_average:number;trend:{date:string;actual:number}[];regions:{region:string;quantity:number}[];inventory:Inventory[]};
function LiveProducts({ctx,path}: {ctx:Context;path:string}) {
  const [query,setQuery]=useState("");const [risk,setRisk]=useState("");const [region,setRegion]=useState("");const [summary,setSummary]=useState<ProductSummary|null>(null);const [detailError,setDetailError]=useState("");const [detailLoading,setDetailLoading]=useState(false);
  const routeId=path.split("?")[0].split("/")[2];const aliases:Record<string,string>={"test-kit-a":"TK-A-001","gloves-b":"GL-B-014","mask-c":"MK-C-028","syringe-d":"SY-D-039","antigen-e":"AG-E-052"};const product=routeId?ctx.state.products.find(p=>String(p.id)===routeId||p.code===aliases[routeId]):undefined;
  const search=query||new URLSearchParams(path.split("?")[1]).get("search")||"";const productId=product?.id;const infoId=ctx.state.info.id;const version=ctx.state.info.data_version;const rpc=ctx.rpc;
  useEffect(()=>{if(!productId)return;let alive=true;async function load(){setDetailLoading(true);try{const next=await rpc<ProductSummary>(`/products/${productId}/summary`);if(alive){setSummary(next);setDetailError("");}}catch(e){if(alive)setDetailError(e instanceof Error?e.message:"โหลดสินค้าไม่ได้");}finally{if(alive)setDetailLoading(false);}}void load();return()=>{alive=false;};
    // Reload detail when the selected product or sales version changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  },[productId,infoId,version]);
  const filtered=ctx.state.products.filter(p=>(p.name+p.code).toLowerCase().includes(search.toLowerCase())&&(!risk||productRisk(ctx.state,p.code)===risk)&&(!region||ctx.state.inventory.some(i=>i.product_code===p.code&&i.region===region)));
  const exportProducts=()=>downloadCsv("product-portfolio.csv",filtered.map(p=>({code:p.code,name:p.name,lead_time_days:p.lead_time_days,safety_stock:p.safety_stock,forecast:currentRun(ctx.state,p.code)?.total,risk:productRisk(ctx.state,p.code)})));
  if(!routeId)return <div className="page-content products-page"><PageIntro title="สินค้าทั้งหมด" description="ดู Forecast, Inventory และความเสี่ยงของ portfolio จากข้อมูลปัจจุบัน" actions={<Button icon="plus" onClick={()=>ctx.navigate("/forecast/new")}>สร้าง Forecast ใหม่</Button>}/><div className="product-toolbar"><div className="toolbar-search"><Icon name="search"/><input aria-label="ค้นหาสินค้า" value={search} onChange={e=>{setQuery(e.target.value);if(path.includes("?"))ctx.navigate("/products");}} placeholder="ค้นหาชื่อสินค้า หรือรหัส..."/></div><select className="select-button" aria-label="ระดับความเสี่ยง" value={risk} onChange={e=>setRisk(e.target.value)}><option value="">ทุก Risk level</option><option>HIGH</option><option>MEDIUM</option><option>LOW</option></select><select className="select-button" aria-label="พื้นที่สินค้า" value={region} onChange={e=>setRegion(e.target.value)}><option value="">ทุก Region</option>{ctx.state.dashboard.regions.map(r=><option key={r.region}>{r.region}</option>)}</select><span className="toolbar-spacer"/><span className="table-result-count">{filtered.length} จาก {ctx.state.products.length} สินค้า</span></div><article className="panel products-table-panel"><div className="panel-heading"><div><span className="panel-kicker">Product portfolio</span><h3>สถานะ Forecast ล่าสุด</h3></div><Button variant="secondary" icon="download" disabled={!filtered.length} onClick={exportProducts}>Export</Button></div><Portfolio state={ctx.state} rows={filtered} navigate={ctx.navigate}/></article></div>;
  if(!product)return <div className="page-content"><EmptyState title="ไม่พบสินค้านี้" detail="สินค้านี้ไม่มีในพื้นที่ทำงานที่เลือก" action="กลับไปสินค้าทั้งหมด" onClick={()=>ctx.navigate("/products")}/></div>;
  const run=currentRun(ctx.state,product.code);const stock=summary?.inventory.length?summary.inventory.reduce((sum,s)=>sum+s.inventory,0):null;const cover=stock!=null&&summary?.daily_average?stock/summary.daily_average:null;
  async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);await ctx.action(async()=>{await ctx.rpc(`/products/${product!.id}`,{name:form.get("name"),lead_time_days:Number(form.get("lead")),safety_stock:Number(form.get("stock"))},"PUT");ctx.notify("บันทึกสินค้าเรียบร้อย");ctx.refresh();});}
  return <div className="page-content product-detail-page"><button className="back-link" onClick={()=>ctx.navigate("/products")}><Icon name="chevron"/>กลับไปสินค้าทั้งหมด</button><PageIntro title={product.name} description={`${product.code} · ข้อมูลถึง ${summary?.last_date||"—"}`} actions={<><Button variant="secondary" icon="download" disabled={!summary} onClick={()=>summary&&downloadCsv(`${product.code}-inventory.csv`,summary.inventory.map(s=>({...s})))}>Export</Button><Button icon="trend" onClick={()=>ctx.navigate(`/forecast/new?product=${encodeURIComponent(product.code)}`)}>สร้าง Forecast จากสินค้านี้</Button></>}/>{detailError&&<p role="alert" className="live-error">{detailError}</p>}{detailLoading&&<p role="status">กำลังอ่านรายละเอียดสินค้า...</p>}<div className="product-detail-banner"><span className="product-detail-avatar">{product.name[0]}</span><div><span className="panel-kicker">Selected product</span><h3>{product.name}</h3><p>{product.code} · Lead time {product.lead_time_days} วัน</p></div><div className="detail-banner-risk"><span>Risk level</span>{run?<RiskBadge risk={productRisk(ctx.state,product.code)}/>:<span className="live-muted">ยังไม่ประเมิน</span>}</div></div><section className="detail-stat-grid"><DetailStat label="Current inventory" value={num(stock)} suffix="units" note="รวม snapshot ล่าสุดของแต่ละพื้นที่" tone="blue"/><DetailStat label="Latest forecast" value={num(run?.total)} suffix="units" note={run?`${run.region} · ${run.horizon} วัน`:"ยังไม่มี Forecast ปัจจุบัน"} tone="teal"/><DetailStat label="Holdout WAPE" value={percent(run?.metrics.wape_percent)} suffix="" note="ความคลาดเคลื่อนย้อนหลัง 28 วัน" tone="purple"/><DetailStat label="Inventory cover" value={num(cover)} suffix="วัน" note="เทียบยอดขายเฉลี่ย 30 วันล่าสุด" tone="orange"/></section><section className="detail-content-grid"><article className="panel chart-panel"><div className="panel-heading"><div><span className="panel-kicker">Demand history</span><h3>ยอดขายย้อนหลังทุกพื้นที่</h3></div></div><ForecastChart units="units" unitsLabel="เฉลี่ยชิ้น/วัน (ช่วงละ 7 วัน)" markerLabel="ข้อมูลล่าสุด" data={chartData(summary?.trend||[])}/></article><aside className="panel inventory-panel"><div className="panel-heading"><div><span className="panel-kicker">Inventory health</span><h3>สถานะคงคลัง</h3></div></div><div className="inventory-gauge"><div className="gauge-circle"><strong>{num(cover)}</strong><span>วัน</span></div><div><span>Stock cover</span><strong>ยอดขายเฉลี่ยต่อวัน</strong><b>{num(summary?.daily_average)} units</b></div></div><p>Snapshot อาจเป็นข้อมูลในอดีต ตรวจสอบวันที่ก่อนใช้สรุปแผนเติมสินค้า</p><Button variant="secondary" onClick={()=>ctx.navigate("/alerts")}>ดูรายการที่ต้องทบทวน</Button></aside></section><Panel title="Demand แยกตาม Region" kicker="Regional demand"><div className="region-bars">{summary?.regions.map(r=><div className="region-bar-row" key={r.region}><span>{r.region}</span><div><i style={{width:`${r.quantity/Math.max(1,...summary.regions.map(v=>v.quantity))*100}%`}}/></div><strong>{num(r.quantity)}</strong></div>)}</div></Panel><Panel title="Inventory snapshot ตามพื้นที่" kicker="Latest snapshots"><DataTable rows={summary?.inventory.map(i=>({...i}))||[]} labels={{region:"Region",sale_date:"วันที่",inventory:"คงคลัง",product_code:"สินค้า"}}/></Panel><form className="panel live-panel" key={`${product.id}-${product.name}-${product.lead_time_days}-${product.safety_stock}`} onSubmit={save}><div className="panel-heading"><div><span className="panel-kicker">Product settings</span><h3>ข้อมูลสินค้าและนโยบาย Inventory</h3></div></div><div className="form-grid"><label className="form-field"><span>ชื่อสินค้า</span><input name="name" defaultValue={product.name} maxLength={120} required/></label><label className="form-field"><span>Lead time (วัน)</span><input name="lead" type="number" min="1" max="365" defaultValue={product.lead_time_days} required/></label><label className="form-field"><span>Safety stock</span><input name="stock" type="number" min="0" max="2147483647" defaultValue={product.safety_stock} required/></label></div><div className="live-spacing"><Button type="submit" disabled={ctx.busy||!ctx.writer} icon="check">บันทึกสินค้า</Button></div></form></div>;
}

function LiveAlerts({ctx,path}: {ctx:Context;path:string}) {
  const [filter,setFilter]=useState("all");const [includeOld,setIncludeOld]=useState(false);const [sort,setSort]=useState("newest");
  const id=Number(path.split("?")[0].split("/")[2]);const selected=ctx.state.alerts.find(a=>a.id===id);const current=ctx.state.alerts.filter(a=>!a.stale);
  const counts={HIGH:current.filter(a=>a.level==="HIGH"&&a.review_status==="pending").length,MEDIUM:current.filter(a=>a.level==="MEDIUM"&&a.review_status==="pending").length,resolved:current.filter(a=>a.review_status!=="pending").length};
  const list=ctx.state.alerts.filter(a=>(includeOld||!a.stale)&&(filter==="all"||filter==="resolved"?filter!=="resolved"||a.review_status!=="pending":a.level===filter));
  if(sort==="oldest")list.reverse();
  const status=(a:Alert)=>a.review_status==="approved"?"ทบทวนแล้ว":a.review_status==="dismissed"?"ไม่ดำเนินการ":"ต้องตรวจสอบ";
  async function review(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!selected)return;const form=new FormData(e.currentTarget);await ctx.action(async()=>{await ctx.rpc(`/alerts/${selected.id}/review`,{status:form.get("status"),note:form.get("note")},"PUT");ctx.notify("บันทึกผลการทบทวนพร้อมผู้ตรวจสอบเรียบร้อย");ctx.refresh();});}
  const routeDetail=path.split("?")[0].split("/").length>2;
  if(routeDetail&&!selected)return <div className="page-content"><EmptyState title="ไม่พบ Alert นี้" detail="รายการนี้ไม่มีในพื้นที่ทำงาน" action="กลับไปแจ้งเตือน" onClick={()=>ctx.navigate("/alerts")}/></div>;
  if(selected){const run=ctx.state.runs.find(r=>r.id===selected.forecast_id);const product=ctx.state.products.find(p=>p.code===run?.product_code);return <div className="page-content alert-detail-page"><button className="back-link" onClick={()=>ctx.navigate("/alerts")}><Icon name="chevron"/>กลับไปแจ้งเตือนทั้งหมด</button><PageIntro title={`Alert #${selected.id}`} description={run?`${product?.name||run.product_code} · ${run.region} · Forecast #${run.id}`:`Forecast #${selected.forecast_id}`}/><section className="alert-detail-hero panel"><span className={`alert-hero-icon alert-icon-${selected.level.toLowerCase()}`}><Icon name="bell"/></span><div><span className="panel-kicker">Early warning</span><h3>{safeText(selected.message)}</h3><p>{selected.stale?"ผลจากข้อมูลรุ่นก่อน · ตรวจข้อมูลปัจจุบันก่อนตัดสินใจ":status(selected)}</p></div><RiskBadge risk={selected.level as RiskLevel}/></section><section className="alert-detail-grid"><Panel title="หลักฐานจาก Forecast" kicker="Forecast evidence">{run?<><section className="detail-stat-grid"><DetailStat label="Forecast" value={num(run.total)} suffix="units" note={`${run.horizon} วัน`} tone="teal"/><DetailStat label="Demand change" value={percent(run.change_percent)} suffix="" note="เทียบค่าเฉลี่ย 28 วัน" tone="orange"/></section><ForecastChart units="units" unitsLabel="เฉลี่ยชิ้น/วัน (ช่วงละ 7 วัน)" markerLabel="Forecast" data={chartData(run.history.slice(-30),run.points)}/><Button variant="secondary" onClick={()=>ctx.navigate(`/forecast/${run.id}`)}>ดูผล Forecast</Button></>:<Button onClick={()=>ctx.navigate(`/forecast/${selected.forecast_id}`)}>เปิดผล Forecast</Button>}</Panel><form className="panel live-panel" key={`${selected.id}-${selected.reviewed_at}`} onSubmit={review}><span className="panel-kicker">Human review</span><h3>บันทึกการตัดสินใจ</h3><p>การบันทึกนี้เก็บผลทบทวนในระบบสำหรับติดตามงาน</p><label className="form-field live-spacing"><span>สถานะ</span><select name="status" defaultValue={selected.review_status}><option value="pending">ต้องตรวจสอบ</option><option value="approved">ทบทวนแล้ว / อนุมัติ</option><option value="dismissed">ไม่ดำเนินการ</option></select></label><label className="form-field live-spacing"><span>เหตุผลประกอบการทบทวน</span><textarea name="note" required maxLength={2000} defaultValue={selected.review_note||""} rows={5}/></label>{selected.reviewed_at&&<p>ทบทวนโดย {ctx.state.members.find(m=>m.id===selected.reviewed_by)?.username||`User #${selected.reviewed_by}`}<br/>{dateText(selected.reviewed_at)}</p>}<Button type="submit" disabled={ctx.busy||!ctx.writer} icon="check">บันทึก Review</Button></form></section></div>;}
  return <div className="page-content alerts-page"><PageIntro title="แจ้งเตือนที่ต้องตัดสินใจ" description="ตรวจจับการเปลี่ยนแปลงของ Demand และความเสี่ยงคงคลัง พร้อมบันทึกการทบทวน" actions={<Button variant="secondary" icon="settings" onClick={()=>ctx.navigate("/settings")}>ตั้งค่า Alert</Button>}/><div className="alert-overview-grid">{[{label:"High priority",value:counts.HIGH,tone:"high"},{label:"Medium priority",value:counts.MEDIUM,tone:"medium"},{label:"Reviewed",value:counts.resolved,tone:"low"}].map(item=><article key={item.label} className={`alert-overview alert-overview-${item.tone}`}><span className="overview-dot"/><span>{item.label}</span><strong>{item.value}</strong><small>ข้อมูลรุ่นปัจจุบัน</small></article>)}<article className="alert-guidance"><Icon name="shield"/><span><strong>Human review</strong><small>ทุกการทบทวนบันทึกผู้ใช้งานและวันเวลา</small></span></article></div><div className="alert-toolbar"><div className="alert-tabs">{[{key:"all",name:"ทั้งหมด"},{key:"HIGH",name:"High"},{key:"MEDIUM",name:"Medium"},{key:"resolved",name:"ทบทวนแล้ว"}].map(item=><button key={item.key} className={filter===item.key?"is-active":""} onClick={()=>setFilter(item.key)}>{item.name}</button>)}</div><select aria-label="เรียงแจ้งเตือน" className="select-button" value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">ล่าสุดก่อน</option><option value="oldest">เก่าสุดก่อน</option></select></div><label className="live-check"><input type="checkbox" checked={includeOld} onChange={e=>setIncludeOld(e.target.checked)}/>แสดงรายการจากข้อมูลรุ่นก่อน</label><div className="alert-list">{list.map(a=>{const run=ctx.state.runs.find(r=>r.id===a.forecast_id);return <article className="alert-card panel" key={a.id}><div className="alert-card-main"><div className="live-toolbar"><RiskBadge risk={a.level as RiskLevel}/><strong>Forecast #{a.forecast_id}</strong><span className="live-muted">{status(a)}{a.stale&&" · ข้อมูลรุ่นก่อน"}</span></div><h3>{safeText(a.message)}</h3><p>{run?`${run.product_code} · ${run.region} · ${dateText(run.created_at)}`:""}</p><Button variant="secondary" onClick={()=>ctx.navigate(`/alerts/${a.id}`)}>ดูรายละเอียดและทบทวน<Icon name="arrow"/></Button></div></article>;})}{!list.length&&<EmptyState title="ไม่มี Alert ในมุมมองนี้" detail="เมื่อผล Forecast พบความเปลี่ยนแปลงหรือความเสี่ยง รายการจะแสดงที่นี่"/>}</div></div>;
}

function LiveMonitoring({ctx}: {ctx:Context}) {
  const [selectedId,setSelectedId]=useState("");const [scope,setScope]=useState("all");const runs=ctx.state.monitor.runs.filter(r=>scope!=="current"||!r.stale);const chosen=runs.find(r=>String(r.id)===selectedId)||runs[0];
  const live=ctx.state.monitor.runs.filter(r=>!r.lineage_changed&&r.live_metrics);const liveWape=live.map(r=>r.live_metrics!.wape_percent).filter((v):v is number=>v!=null);const latest=ctx.state.runs[0];const needsReview=ctx.state.monitor.runs.filter(r=>!r.lineage_changed&&(r.live_metrics?.wape_percent??r.holdout.wape_percent??0)>25);
  return <div className="page-content monitoring-page"><PageIntro title="ติดตามผลจริงเทียบ Forecast" description="เปรียบเทียบยอดขายที่นำเข้าหลังวันพยากรณ์ และติดตามความคลาดเคลื่อนของโมเดล" actions={<><Button variant="secondary" icon="upload" onClick={()=>ctx.navigate("/data/upload")}>นำเข้ายอดขายล่าสุด</Button><Button icon="refresh" onClick={()=>ctx.navigate(chosen?`/forecast/new?product=${encodeURIComponent(chosen.product_code)}&region=${encodeURIComponent(chosen.region)}`:"/forecast/new")}>สร้าง Re-forecast</Button></>}/><section className="monitor-kpi-grid"><KpiCard label="Live WAPE" value={percent(liveWape.length?liveWape.reduce((a,b)=>a+b,0)/liveWape.length:null)} detail="ค่าเฉลี่ยรอบที่มียอดขายในวันที่พยากรณ์" change="ยิ่งต่ำยิ่งดี" tone="blue" icon="shield" isTextChange/><KpiCard label="Matched actual days" value={num(live.reduce((sum,r)=>sum+r.matched_days,0))} detail="จำนวนวันจากทุกรอบที่เทียบยอดขายได้" change="จากข้อมูลนำเข้า" tone="teal" icon="trend" isTextChange/><KpiCard label="Model review needed" value={num(needsReview.length)} detail="รอบที่มี WAPE มากกว่า 25%" change="ต้องทบทวน" tone="orange" icon="bell" isTextChange/><KpiCard label="Latest forecast" value={latest?`#${latest.id}`:"—"} detail={latest?dateText(latest.created_at):"ยังไม่มี Forecast"} change="บันทึกในระบบ" tone="purple" icon="refresh" isTextChange/></section><section className="monitor-main-grid"><article className="panel chart-panel"><div className="panel-heading"><div><span className="panel-kicker">Portfolio monitoring</span><h3>Actual vs Forecast performance</h3></div><select className="select-button" aria-label="รอบ Forecast ที่ติดตาม" value={chosen?.id??""} onChange={e=>setSelectedId(e.target.value)}>{runs.map(r=><option key={r.id} value={r.id}>#{r.id} {r.product_code} / {r.region}</option>)}</select></div>{chosen?.actual_vs_forecast.length?<><ForecastChart units="units" markerLabel="" data={chosen.actual_vs_forecast.map(p=>({label:p.date.slice(5),actual:p.actual,forecast:p.forecast}))}/><DataTable rows={chosen.actual_vs_forecast.map(p=>({Date:p.date,Actual:p.actual,Forecast:p.forecast}))}/></>:<EmptyState title={chosen?.lineage_changed?"ข้อมูลรอบนี้ถูกแทนที่แล้ว":"รอยอดขายหลังวันต้นกำเนิด Forecast"} detail={chosen?.lineage_changed?"ผลรอบนี้คงไว้ในประวัติ และไม่เทียบกับยอดขายของชุดใหม่":"นำเข้ายอดขายในวันที่พยากรณ์ ระบบจะคำนวณ Live metrics ให้อัตโนมัติ"} action="นำเข้ายอดขาย" onClick={()=>ctx.navigate("/data/upload")}/>}</article><aside className="panel monitor-status-panel"><div className="panel-heading"><div><span className="panel-kicker">Model health</span><h3>สถานะรอบที่เลือก</h3></div></div><div className="model-health-score"><strong>{percent(chosen?.live_metrics?.wape_percent)}</strong><span>Live WAPE</span></div><div className="model-list"><div><span><strong>Holdout WAPE</strong><small>การทดสอบย้อนหลัง</small></span><b>{percent(chosen?.holdout.wape_percent)}</b></div><div><span><strong>Live MAE</strong><small>ความคลาดเคลื่อนเฉลี่ย / วัน</small></span><b>{num(chosen?.live_metrics?.mae)}</b></div><div><span><strong>Matched actuals</strong><small>วันที่มียอดขายแล้ว</small></span><b>{num(chosen?.matched_days)}</b></div></div>{chosen&&<Button variant="secondary" onClick={()=>ctx.navigate(`/forecast/${chosen.id}`)}>ดูผลและโมเดล<Icon name="arrow"/></Button>}</aside></section><Panel title="รอบการพยากรณ์ที่ติดตาม" kicker="Forecast monitoring" actions={<select aria-label="มุมมองรอบพยากรณ์" className="select-button" value={scope} onChange={e=>setScope(e.target.value)}><option value="all">ทุกรอบ</option><option value="current">ข้อมูลรุ่นปัจจุบัน</option></select>}><DataTable rows={runs.map(r=>({Run:r.id,Product:r.product_code,Region:r.region,Holdout_WAPE:r.holdout.wape_percent,Live_WAPE:r.live_metrics?.wape_percent,Actual_days:r.matched_days,Status:r.lineage_changed?"ชุดข้อมูลถูกแทนที่":r.stale?"ข้อมูลรุ่นก่อน":"ปัจจุบัน"}))}/></Panel>{chosen&&<Panel title="ผลทดสอบย้อนหลัง 28 วัน" kicker="Untouched holdout"><DataTable rows={chosen.backtest.map(p=>({Date:p.date,Actual:p.actual,Forecast:p.forecast}))}/></Panel>}<section className="panel timeline-panel"><div className="panel-heading"><div><span className="panel-kicker">Monitor loop</span><h3>ประวัติการอัปเดต</h3></div></div><div className="monitor-timeline">{ctx.state.monitor.events.map((event,i)=><TimelineItem key={`${event.created_at}-${i}`} date={dateText(event.created_at)} title={event.action} detail={event.action.startsWith("mock_erp")?"เพิ่มรายการยอดขายจากการทดสอบระบบเดิม":safeText(event.detail)} active={i===0}/>)}</div>{!ctx.state.monitor.events.length&&<EmptyState title="ยังไม่มีประวัติการอัปเดต" detail="การนำเข้า คำนวณ และทบทวนจะแสดงที่นี่"/>}</section></div>;
}

function LiveSettings({ctx,user,path,onLogout,onChangePassword}: {ctx:Context;user:AuthUser;path:string;onLogout:()=>Promise<void>;onChangePassword:(v:{current_password:string;new_password:string})=>Promise<void>}) {
  const [section,setSection]=useState(new URLSearchParams(path.split("?")[1]).get("section")==="help"?"help":"workspace");const [member,setMember]=useState("");const [role,setRole]=useState("planner");const [current,setCurrent]=useState("");const [password,setPassword]=useState("");const [confirm,setConfirm]=useState("");const info=ctx.state.info;
  async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);await ctx.action(async()=>{await ctx.rpc("/settings",{name:form.get("name"),auto_refresh:form.has("refresh"),compact_table:form.has("compact"),alert_threshold_percent:Number(form.get("threshold"))},"PUT");ctx.notify("บันทึกการตั้งค่าเรียบร้อย");ctx.refresh();});}
  async function saveMember(e:FormEvent){e.preventDefault();await ctx.action(async()=>{await ctx.rpc("/members",{username:member,role},"PUT");setMember("");ctx.notify("บันทึกสมาชิกทีมเรียบร้อย");ctx.refresh();});}
  async function change(e:FormEvent){e.preventDefault();await ctx.action(async()=>{if(password!==confirm)throw new Error("รหัสผ่านใหม่และการยืนยันไม่ตรงกัน");await onChangePassword({current_password:current,new_password:password});setCurrent("");setPassword("");setConfirm("");});}
  return <div className="page-content settings-page"><PageIntro title="ตั้งค่าพื้นที่ทำงาน" description="จัดการการแจ้งเตือน รูปแบบการใช้งาน สมาชิกทีม และความปลอดภัยของบัญชี"/><div className="settings-layout"><div className="settings-nav panel">{[{id:"workspace",name:"Workspace",detail:"พื้นที่ทำงาน",icon:"settings"},{id:"team",name:"Team members",detail:"สมาชิกในทีม",icon:"grid"},{id:"security",name:"Account security",detail:"ความปลอดภัย",icon:"lock"},{id:"help",name:"คู่มือใช้งาน",detail:"ขั้นตอนการทำงาน",icon:"help"}].map(s=><button className={`settings-nav-item ${section===s.id?"is-active":""}`} key={s.id} onClick={()=>setSection(s.id)}><Icon name={s.icon}/><span><strong>{s.name}</strong><small>{s.detail}</small></span><Icon name="chevron"/></button>)}<button className="settings-nav-item" onClick={()=>ctx.navigate("/data/upload")}><Icon name="database"/><span><strong>Data mapping</strong><small>การจับคู่ข้อมูล</small></span><Icon name="chevron"/></button></div><div className="settings-sections">
    {section==="workspace"&&<form onSubmit={save} key={`${info.id}-${info.name}-${JSON.stringify(info.settings)}`}><section className="panel settings-card"><div className="settings-card-heading"><div><span className="panel-kicker">Workspace preferences</span><h3>พื้นที่ทำงานและการแจ้งเตือน</h3></div><Icon name="settings"/></div><div className="form-grid"><label className="form-field"><span>ชื่อพื้นที่ทำงาน</span><input name="name" defaultValue={cleanName(info.name)} required maxLength={120} disabled={!ctx.manager}/></label><label className="form-field"><span>Demand alert threshold (%)</span><input name="threshold" type="number" min="5" max="100" defaultValue={info.settings.alert_threshold_percent??15} required disabled={!ctx.manager}/></label></div><label className="live-check"><input name="refresh" type="checkbox" defaultChecked={info.settings.auto_refresh??true} disabled={!ctx.manager}/>Auto refresh data · ทุก 15 นาที</label><label className="live-check"><input name="compact" type="checkbox" defaultChecked={info.settings.compact_table??false} disabled={!ctx.manager}/>Compact product table</label><p>ระบบแจ้งเตือนผ่านหน้า Alerts และปุ่มแจ้งเตือนด้านบน</p><Button type="submit" icon="check" disabled={ctx.busy||!ctx.manager}>บันทึกการเปลี่ยนแปลง</Button></section></form>}
    {section==="team"&&<section className="panel settings-card"><div className="settings-card-heading"><div><span className="panel-kicker">Team members</span><h3>สมาชิกในทีม</h3></div></div><p>Owner จัดการสมาชิก · Admin ตั้งค่าและข้อมูล · Planner นำเข้า พยากรณ์ และทบทวน · Viewer อ่านอย่างเดียว</p><DataTable rows={ctx.state.members.map(m=>({User:m.username,Role:m.role}))}/>{info.role==="owner"&&<><form className="live-toolbar live-spacing" onSubmit={saveMember}><label className="form-field"><span>Username ที่สมัครแล้ว</span><input value={member} onChange={e=>setMember(e.target.value)} required minLength={3} maxLength={32}/></label><label className="form-field"><span>สิทธิ์</span><select value={role} onChange={e=>setRole(e.target.value)}><option value="planner">Planner</option><option value="viewer">Viewer</option><option value="admin">Admin</option></select></label><Button type="submit" icon="plus" disabled={ctx.busy}>เพิ่ม / เปลี่ยนสิทธิ์</Button></form><div className="live-team-actions">{ctx.state.members.filter(m=>m.role!=="owner").map(m=><Button key={m.id} variant="danger" disabled={ctx.busy} onClick={()=>void ctx.action(async()=>{await ctx.rpc(`/members/${m.id}`,undefined,"DELETE");ctx.notify(`นำ ${m.username} ออกจากทีมแล้ว`);ctx.refresh();})}>นำ {m.username} ออกจากทีม</Button>)}</div></>}</section>}
    {section==="security"&&<section className="panel settings-card"><div className="settings-card-heading"><div><span className="panel-kicker">Account security</span><h3>เปลี่ยนรหัสผ่าน</h3></div><Icon name="lock"/></div><form className="settings-security-form" onSubmit={change}><label className="form-field"><span>รหัสผ่านปัจจุบัน</span><input type="password" autoComplete="current-password" required value={current} onChange={e=>setCurrent(e.target.value)}/></label><label className="form-field"><span>รหัสผ่านใหม่</span><input type="password" autoComplete="new-password" required minLength={8} maxLength={128} value={password} onChange={e=>setPassword(e.target.value)}/></label><label className="form-field"><span>ยืนยันรหัสผ่านใหม่</span><input type="password" autoComplete="new-password" required minLength={8} maxLength={128} value={confirm} onChange={e=>setConfirm(e.target.value)}/></label><p>เมื่อเปลี่ยนสำเร็จ ทุก session เดิมจะหมดสิทธิ์ และต้องเข้าสู่ระบบใหม่</p><Button type="submit" disabled={ctx.busy} icon="lock">เปลี่ยนรหัสผ่าน</Button></form></section>}
    {section==="help"&&<section className="panel settings-card"><span className="panel-kicker">User guide</span><h3>ใช้งานจาก Data ถึง Monitoring</h3><ol className="live-guide"><li>นำเข้า CSV/XLSX หรือเลือกชุดข้อมูลจาก Data library</li><li>ตรวจ Preview และ Column mapping แล้วแก้ข้อมูลผิดก่อนบันทึก</li><li>เลือกเพิ่มยอดขาย หรือแทนที่ชุดเดิม และยืนยันรายการซ้ำ</li><li>สร้าง Forecast ตามสินค้า พื้นที่ และระยะเวลา 7–180 วัน</li><li>ตรวจ WAPE, MAE, Inventory snapshot และช่วงความไม่แน่นอน</li><li>บันทึกการทบทวนใน Alerts พร้อมเหตุผล</li><li>นำเข้ายอดขายวันที่พยากรณ์เพื่อวัดผลใน Monitoring และสร้าง Re-forecast</li></ol><Button onClick={()=>ctx.navigate("/data/upload")}>เริ่มนำเข้าข้อมูล</Button></section>}
    <section className="panel workspace-profile-card"><span className="workspace-avatar large-avatar">{(user.full_name||user.username).slice(0,2).toUpperCase()}</span><div><span className="panel-kicker">Current workspace</span><h3>{cleanName(info.name)}</h3><p>{ctx.state.members.length} สมาชิก · สิทธิ์ {info.role}</p></div><Button variant="danger" icon="close" disabled={ctx.busy} onClick={()=>void onLogout()}>ออกจากระบบ</Button></section>
  </div></div></div>;
}
